import{_ as t,a0 as o,w as d,s as r,ao as l,I as e,x as a,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"一起來學習 Lisp 編程語言吧！ | LCTT x X-CMD","titleTemplate":false,"description":"一起來學習 Lisp 編程語言吧！ | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一起來學習 Lisp 編程語言吧！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一起來學習 Lisp 編程語言吧！ | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20210503 Learn the Lisp programming language in 2021","title":"一起來學習 Lisp 編程語言吧！","tag":"202206","desc":""},"relativePath":"202206/20210503 Learn the Lisp programming language in 2021.md","filePath":"[post].md"}'),g={name:"202206/20210503 Learn the Lisp programming language in 2021.md"};function h(c,s,u,k,b,f){const n=o("Link");return d(),r("div",null,[s[40]||(s[40]=l('<h1 id="一起來學習-lisp-編程語言吧" tabindex="-1">一起來學習 Lisp 編程語言吧！ <a class="header-anchor" href="#一起來學習-lisp-編程語言吧" aria-label="Permalink to “一起來學習 Lisp 編程語言吧！”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/24/124147v0loy4e3y0hneih8.jpg" alt=""></p><blockquote><p>許多大型代碼庫中都有 Lisp 代碼的身影，因此，熟悉一下這門語言是一個明智之舉。</p></blockquote><p>早在 1958 年，Lisp 就被髮明出來了，它是世界上第二古老的計算機編程語言（LCTT 譯註：最古老的編程語言是 Fortran，誕生於 1957 年）。它有許多現代的衍生品，包括 Common Lisp、Emacs Lisp（Elisp）、Clojure、Racket、Scheme、Fennel 和 GNU Guile 等。</p><p>那些喜歡思考編程語言的設計的人，往往都喜歡 Lisp，因為它的語法和數據有着相同的結構：Lisp 代碼實際上是<ruby>一個列表的列表<rt>a list of lists</rt></ruby>，它的名字其實是 “<ruby>列表處理<rt>LISt Processing</rt></ruby>” 的簡寫。而那些喜歡思考編程語言的美學的人，往往都討厭 Lisp，因為它經常使用括號來定義範圍；事實上，編程界也有一個廣為流傳的笑話：Lisp 代表的其實是 <ruby>“大量煩人的多餘括號”<rt>Lots of Irritating Superfluous Parentheses</rt></ruby>。</p><p>不管你是喜歡還是討厭 Lisp 的設計哲學，你都不得不承認，它都是一門有趣的語言，過去如此，現在亦然（這得歸功於現代方言 Clojure 和 Guile）。你可能會驚訝於在任何特定行業的大代碼庫中潛伏着多少 Lisp 代碼，因此，現在開始學習 Lisp，至少熟悉一下它，不失為一個好主意。</p><h3 id="安裝-lisp" tabindex="-1">安裝 Lisp <a class="header-anchor" href="#安裝-lisp" aria-label="Permalink to “安裝 Lisp”">​</a></h3>',7)),e("p",null,[s[3]||(s[3]=a("Lisp 有很多不同的實現。比較流行的開源版本有 ",-1)),i(n,{href:"http://sbcl.org"},{default:p(()=>[...s[0]||(s[0]=[a("SBCL",-1)])]),_:1}),s[4]||(s[4]=a("、",-1)),i(n,{href:"http://clisp.org"},{default:p(()=>[...s[1]||(s[1]=[a("GNU Lisp",-1)])]),_:1}),s[5]||(s[5]=a(" 和 ",-1)),i(n,{href:"https://www.gnu.org/software/gcl/"},{default:p(()=>[...s[2]||(s[2]=[a("GNU Common Lisp",-1)])]),_:1}),s[6]||(s[6]=a("（GCL）。你可以使用發行版的包管理器安裝它們中的任意一個，在本文中，我是用的是 ",-1)),s[7]||(s[7]=e("code",null,"clisp",-1)),s[8]||(s[8]=a("（LCTT 譯註：也就是 GNU Lisp，一種 ANSI Common Lisp 的實現）。",-1))]),s[41]||(s[41]=l('<p>以下是在不同的 Linux 發行版中安裝 <code>clisp</code> 的步驟。</p><p>在 Fedora Linux 上，使用 <code>dnf</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install clisp</span></span></code></pre></div><p>在 Debian 上，使用 <code>apt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install clisp</span></span></code></pre></div>',5)),e("p",null,[s[11]||(s[11]=a("在 macOS 上，使用 ",-1)),i(n,{href:"https://opensource.com/article/20/11/macports"},{default:p(()=>[...s[9]||(s[9]=[a("MacPorts",-1)])]),_:1}),s[12]||(s[12]=a(" 或者 ",-1)),i(n,{href:"https://opensource.com/article/20/6/homebrew-linux"},{default:p(()=>[...s[10]||(s[10]=[a("Homebrew",-1)])]),_:1}),s[13]||(s[13]=a("：",-1))]),s[42]||(s[42]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 使用 MacPorts</span></span>
<span class="line"><span>$ sudo port install clisp</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 使用 Homebrew</span></span>
<span class="line"><span>$ brew install clisp</span></span></code></pre></div>`,1)),e("p",null,[s[16]||(s[16]=a("在 Windows 上，你可以使用 ",-1)),i(n,{href:"https://cygwin.fandom.com/wiki/Clisp"},{default:p(()=>[...s[14]||(s[14]=[a("clisp on Cygwin",-1)])]),_:1}),s[17]||(s[17]=a(" 或者從 ",-1)),i(n,{href:"http://mirror.lagoon.nc/gnu/gcl/binaries/stable"},{default:p(()=>[...s[15]||(s[15]=[a("gnu.org/software/gcl",-1)])]),_:1}),s[18]||(s[18]=a(" 上下載 GCL 的二進制文件。",-1))]),s[43]||(s[43]=l(`<p>雖然我使用 <code>clisp</code> 命令來運行 Lisp 代碼，但是本文中涉及到的大多數語法規則，對任何 Lisp 實現都是適用的。如果你選擇使用一個不同的 Lisp 實現，除了用來運行 Lisp 代碼的命令會和我不一樣外（比如，你可能要用 <code>gcl</code> 或 <code>sbcl</code> 而不是 <code>clisp</code>），其它的所有東西都是相同的。</p><h3 id="列表處理" tabindex="-1">列表處理 <a class="header-anchor" href="#列表處理" aria-label="Permalink to “列表處理”">​</a></h3><p>Lisp 源代碼的基本單元是 “<ruby>表達式<rt>expression</rt></ruby>”，它在形式上是一個列表。舉個例子，下面就是一個列表，它由一個操作符（<code>+</code>）和兩個整數（<code>1</code> 和 <code>2</code>）組成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(+ 1 2)</span></span></code></pre></div><p>同時，它也是一個 Lisp 表達式，內容是一個符號（<code>+</code>，會被解析成一個加法函數）和它的兩個參數（<code>1</code> 和 <code>2</code>）。你可以在 Common Lisp 的交互式環境（即 REPL）中運行該表達式和其它表達式。如果你熟悉 Python 的 IDLE，那麼你應該會對 Lisp 的 REPL 感到親切。（LCTT 譯註：REPL 的全稱是 “Read-Eval-Print Loop”，意思是 “‘讀取-求值-輸出’循環”，這個名字很好地描述了它的工作過程。）</p><p>要進入到 REPL 中，只需運行 Common Lisp 即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ clisp</span></span>
<span class="line"><span>[1]&gt;</span></span></code></pre></div><p>在 REPL 提示符中，嘗試輸入一些表達式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (+ 1 2)</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>[2]&gt; (- 1 2)</span></span>
<span class="line"><span>-1</span></span>
<span class="line"><span>[3]&gt; (- 2 1)</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>[4]&gt; (+ 2 3 4)</span></span>
<span class="line"><span>9</span></span></code></pre></div><h3 id="函數" tabindex="-1">函數 <a class="header-anchor" href="#函數" aria-label="Permalink to “函數”">​</a></h3><p>在瞭解了 Lisp 表達式的基本結構後，你可以使用函數來做更多有用的事。譬如，<code>print</code> 函數可以接受任意數量的參數，然後把它們都顯示在你的終端上，<code>pprint</code> 函數還可以實現格式化打印。還有更多不同的打印函數，不過，<code>pprint</code> 在 REPL 中的效果就挺好的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (pprint &quot;hello world&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;hello world&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[2]&gt;</span></span></code></pre></div><p>你可以使用 <code>defun</code> 函數來創建一個自定義函數。<code>defun</code> 函數需要你提供自定義函數的名稱，以及它接受的參數列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (defun myprinter (s) (pprint s))</span></span>
<span class="line"><span>MYPRINTER</span></span>
<span class="line"><span>[2]&gt; (myprinter &quot;hello world&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;hello world&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[3]&gt;</span></span></code></pre></div><h3 id="變量" tabindex="-1">變量 <a class="header-anchor" href="#變量" aria-label="Permalink to “變量”">​</a></h3><p>你可以使用 <code>setf</code> 函數來在 Lisp 中創建變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (setf foo &quot;hello world&quot;)</span></span>
<span class="line"><span>&quot;hello world&quot;</span></span>
<span class="line"><span>[2]&gt; (pprint foo)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;hello world&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[3]&gt;</span></span></code></pre></div><p>你可以在表達式裏嵌套表達式（就像使用某種管道一樣）。舉個例子，你可以先使用 <code>string-upcase</code> 函數，把某個字符串的所有字符轉換成大寫，然後再使用 <code>pprint</code> 函數，將它的內容格式化打印到終端上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[3]&gt; (pprint (string-upcase foo))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;HELLO WORLD&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[4]&gt;</span></span></code></pre></div><p>Lisp 是動態類型語言，這意味着，你在給變量賦值時不需要聲明它的類型。Lisp 默認會把整數當作整數來處理：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (setf foo 2)</span></span>
<span class="line"><span>[2]&gt; (setf bar 3)</span></span>
<span class="line"><span>[3]&gt; (+ foo bar)</span></span>
<span class="line"><span>5</span></span></code></pre></div><p>如果你想讓整數被當作字符串來處理，你可以給它加上引號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[4]&gt; (setf foo &quot;2&quot;)</span></span>
<span class="line"><span>&quot;2&quot;</span></span>
<span class="line"><span>[5]&gt; (setf bar &quot;3&quot;)</span></span>
<span class="line"><span>&quot;3&quot;</span></span>
<span class="line"><span>[6]&gt; (+ foo bar)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>*** - +: &quot;2&quot; is not a number</span></span>
<span class="line"><span>The following restarts are available:</span></span>
<span class="line"><span>USE-VALUE      :R1      Input a value to be used instead.</span></span>
<span class="line"><span>ABORT          :R2      Abort main loop</span></span>
<span class="line"><span>Break 1 [7]&gt;</span></span></code></pre></div><p>在這個示例 REPL 會話中，變量 <code>foo</code> 和 <code>bar</code> 都被賦值為加了引號的數字，因此，Lisp 會把它們當作字符串來處理。數學運算符不能夠用在字符串上，因此 REPL 進入了調試器模式。想要跳出這個調試器，你需要按下 <code>Ctrl+D</code> 才行（LCTT 譯註：就 <code>clisp</code> 而言，使用 <code>quit</code> 關鍵字也可以退出）。</p><p>你可以使用 <code>typep</code> 函數對一些對象進行類型檢查，它可以測試對象是否為某個特定數據類型。返回值 <code>T</code> 和 <code>NIL</code> 分別代表 <code>True</code> 和 <code>False</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[4]&gt; (typep foo &#39;string)</span></span>
<span class="line"><span>NIL</span></span>
<span class="line"><span>[5]&gt; (typep foo &#39;integer)</span></span>
<span class="line"><span>T</span></span></code></pre></div><p><code>string</code> 和 <code>integer</code> 前面加上了一個單引號（<code>&#39;</code>），這是為了防止 Lisp（錯誤地）把這兩個單詞當作是變量來求值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[6]&gt; (typep foo string)</span></span>
<span class="line"><span>*** - SYSTEM::READ-EVAL-PRINT: variable STRING has no value</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>這是一種保護某些術語（LCTT 譯註：類似於字符串轉義）的簡便方法，正常情況下它是用 <code>quote</code> 函數來實現的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[7]&gt; (typep foo (quote string))</span></span>
<span class="line"><span>NIL</span></span>
<span class="line"><span>[5]&gt; (typep foo (quote integer))</span></span>
<span class="line"><span>T</span></span></code></pre></div><h3 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to “列表”">​</a></h3><p>不出人意料，你當然也可以在 Lisp 中創建列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (setf foo (list &quot;hello&quot; &quot;world&quot;))</span></span>
<span class="line"><span>(&quot;hello&quot; &quot;world&quot;)</span></span></code></pre></div><p>你可以使用 <code>nth</code> 函數來索引列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[2]&gt; (nth 0 foo)</span></span>
<span class="line"><span>&quot;hello&quot;</span></span>
<span class="line"><span>[3]&gt; (pprint (string-capitalize (nth 1 foo)))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;World&quot;</span></span></code></pre></div><h3 id="退出-repl" tabindex="-1">退出 REPL <a class="header-anchor" href="#退出-repl" aria-label="Permalink to “退出 REPL”">​</a></h3><p>要結束一個 REPL 會話，你需要按下鍵盤上的 <code>Ctrl+D</code>，或者是使用 Lisp 的 <code>quit</code> 關鍵字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[99]&gt; (quit)</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="編寫腳本" tabindex="-1">編寫腳本 <a class="header-anchor" href="#編寫腳本" aria-label="Permalink to “編寫腳本”">​</a></h3>`,39)),e("p",null,[s[20]||(s[20]=a("Lisp 可以被編譯，也可以作為解釋型的腳本語言來使用。在你剛開始學習的時候，後者很可能是最容易的方式，特別是當你已經熟悉 Python 或 ",-1)),i(n,{href:"https://opensource.com/article/20/4/bash-programming-guide"},{default:p(()=>[...s[19]||(s[19]=[a("Shell 腳本",-1)])]),_:1}),s[21]||(s[21]=a(" 時。",-1))]),s[44]||(s[44]=l(`<p>下面是一個用 Common Lisp 編寫的簡單的“擲骰子”腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/clisp</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(defun roller (num)  </span></span>
<span class="line"><span>  (pprint (random (parse-integer (nth 0 num))))</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(setf userput *args*)</span></span>
<span class="line"><span>(setf *random-state* (make-random-state t))</span></span>
<span class="line"><span>(roller userput)</span></span></code></pre></div><p>腳本的第一行註釋（LCTT 譯註：稱之為“<ruby>釋伴<rt>shebang</rt></ruby>”）告訴了你的 POSIX 終端，該使用什麼可執行文件來運行這個腳本。</p><p><code>roller</code> 函數使用 <code>defun</code> 函數創建，它在內部使用 <code>random</code> 函數來打印一個偽隨機數，這個偽隨機數嚴格小於 <code>num</code> 列表中下標為 0 的元素。在腳本中，這個 <code>num</code> 列表還沒有被創建，不過沒關係，因為只有當腳本被調用時，函數才會執行。</p><p>接下來的那一行，我們把運行腳本時提供的任意參數，都賦值給一個叫做 <code>userput</code> 的變量。這個 <code>userput</code> 變量是一個列表，當它被傳遞給 <code>roller</code> 函數後，它就會變成參數 <code>num</code>。</p><p>腳本的倒數第二行產生了一個“隨機種子”。這為 Lisp 提供了足夠的隨機性來生成一個幾乎隨機的數字。</p><p>最後一行調用了自定義的 <code>roller</code> 函數，並將 <code>userput</code> 列表作為唯一的參數傳遞給它。</p><p>將這個文件保存為 <code>dice.lisp</code>，並賦予它可執行權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x dice.lisp</span></span></code></pre></div><p>最後，運行它，並給它提供一個數字，以作為它選擇隨機數的最大值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./dice.lisp 21</span></span>
<span class="line"><span></span></span>
<span class="line"><span>13</span></span>
<span class="line"><span>$ ./dice.lisp 21</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7</span></span>
<span class="line"><span>$ ./dice.lisp 21</span></span>
<span class="line"><span></span></span>
<span class="line"><span>20</span></span></code></pre></div><p>看起來還不錯！</p><p>你或許注意到，你的模擬骰子有可能會是 0，並且永遠達不到你提供給它的最大值參數。換句話説，對於一個 20 面的骰子，這個腳本永遠投不出 20（除非你把 0 當作 20）。有一個簡單的解決辦法，它只需要用到在本文中介紹的知識，你能夠想到嗎？</p><h3 id="學習-lisp" tabindex="-1">學習 Lisp <a class="header-anchor" href="#學習-lisp" aria-label="Permalink to “學習 Lisp”">​</a></h3>`,14)),e("p",null,[s[23]||(s[23]=a("無論你是想將 Lisp 作為個人腳本的實用語言，還是為了助力你的職業生涯，抑或是僅僅作為一個有趣的實驗，你都可以去看看一年一度（LCTT 譯註：應該是兩年一度）的 ",-1)),i(n,{href:"https://itch.io/jam/spring-lisp-game-jam-2021"},{default:p(()=>[...s[22]||(s[22]=[a("Lisp ",-1),e("ruby",null,[a("遊戲果醬"),e("rt",null,"Game Jam")],-1)])]),_:1}),s[24]||(s[24]=a("，從而收穫一些特別有創意的用途（其中的大多數提交都是開源的，因此你可以查看代碼以從中學習）。",-1))]),s[45]||(s[45]=e("p",null,"Lisp 是一門有趣而獨特的語言，它有着不斷增長的開發者用户羣、足夠悠久的歷史和新興的方言，因此，它有能力讓從事各個行業的程序員都滿意。",-1)),s[46]||(s[46]=e("hr",null,null,-1)),e("p",null,[s[26]||(s[26]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/21/5/learn-lisp"},{default:p(()=>[...s[25]||(s[25]=[a("https://opensource.com/article/21/5/learn-lisp",-1)])]),_:1})]),e("p",null,[s[31]||(s[31]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[27]||(s[27]=[a("Seth Kenlon",-1)])]),_:1}),s[32]||(s[32]=a(" 選題：",-1)),i(n,{href:"https://github.com/lkxed"},{default:p(()=>[...s[28]||(s[28]=[a("lkxed",-1)])]),_:1}),s[33]||(s[33]=a(" 譯者：",-1)),i(n,{href:"https://github.com/lkxed"},{default:p(()=>[...s[29]||(s[29]=[a("lkxed",-1)])]),_:1}),s[34]||(s[34]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[30]||(s[30]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[37]||(s[37]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[35]||(s[35]=[a("LCTT",-1)])]),_:1}),s[38]||(s[38]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:p(()=>[...s[36]||(s[36]=[a("Linux中國",-1)])]),_:1}),s[39]||(s[39]=a(" 榮譽推出",-1))])])}const C=t(g,[["render",h]]);export{y as __pageData,C as default};
